window.docContents[184].resolve({"/Overview/#Cvc___lean----High-Level-CVC5-API--Overview--Typed-terms":{"contents":"\n\nSolver creation and typed terms with their smt! syntax extension. Notice that terms carry their\nsort at type-level.\n\nopen Typed in\ndef setup : Env (Solver × Term Bool × Term Int) := do\n  let solver ← Solver.new\n  solver.setOption \"produce-models\" \"true\"\n  let b1 ← Term.mkSymbol \"b1\"\n  let i1 ← Term.mkSymbol \"i1\"\n  let formula ← smt! ¬ b1 ∨ (b1 ∧ 0 < i1)\n  solver.assert formula\n  return (solver, b1, i1)\n\n\nSimple check-sat.\n\n#eval Env.runIO do\n  let (solver, b1, i1) ← setup\n  println! \"check-sat\"\n  for f in ← solver.getAssertions do println! \"∧ {f}\"\n  solver.checkSat\n    (ifSat := do\n      let b1 ← solver.getValue b1\n      let i1 ← solver.getValue i1\n      println! \"→ sat: b1 ↦ {b1}, i1 ↦ {i1}\")\n\n\ncheck-sat\n∧ (or (not b1) (and b1 (< 0 i1)))\n→ sat: b1 ↦ false, i1 ↦ 0\n\n\nCheck-sat with assumptions.\n\nopen Typed in #eval Env.runIO do\n  let (solver, b1, i1) ← setup\n  println! \"check-sat assuming {b1}\"\n  solver.checkSat (assuming := #[b1])\n    (ifSat := do\n      let b1 ← solver.getValue b1\n      let i1 ← solver.getValue i1\n      println! \"→ sat: b1 := {b1}, i1 := {i1}\")\n\n  let i1_eq_zero ← smt! i1 = 0\n  println! \"check-sat assuming {b1} and {i1_eq_zero}\"\n  solver.checkSat (assuming := #[b1, i1_eq_zero])\n    (ifSat := println! \"→ sat, unexpected!\")\n    (ifUnsat := println! \"→ unsat\")\n    (ifUnknown := fun reason =>\n      println! \"→ solver could not decide 😥:\\n  {reason}\")\n\n\ncheck-sat assuming b1\n→ sat: b1 := true, i1 := 1\ncheck-sat assuming b1 and (= i1 0)\n→ unsat\n\n\nUniversal quantification:\n\nopen Typed in #eval Env.runIO do\n  let solver ← Solver.new\n  let f1 ← smt! ∀ (x y : Int), x + y = y + x\n  solver.assert f1\n  solver.checkSat\n    (ifSat := do println! \"sat\")\n    (ifUnsat := do println! \"unsat\")\n\n\nsat\n\n\nQuantifier elimination:\n\nopen Typed in #eval Env.runIO do\n  let solver ← Solver.new\n  let y ← Term.mkSymbol \"y\"\n  let f ← smt! ∃ (x : Int), 0 < x ∧ x < 5 ∧ 2 * y = x - 1\n  let elim ← solver.qe f\n  println! \"elim := {elim}\"\n\n\nelim := (and (>= y 0) (not (>= y 2)))\n\n\n\n\n","context":"Cvc.lean -- High-Level CVC5 API\u0009Overview","header":"1.1. Typed terms","id":"/Overview/#Cvc___lean----High-Level-CVC5-API--Overview--Typed-terms"}});